head.script:
scwin.gVar = {
    "cPlaceholder" : "",
    "cRef" : "",
    "cReadOnly" : "",
    "cDisabled" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > placeholder]<br/>Secret 컴포넌트의 입력값이 없을때 표시될 PlaceHolder 텍스트를 설정합니다.",
    "validation" : [
        "ref 속성으로 DataCollection 을 바인딩 한 데이터가 빈값인 경우 PlaceHolder 텍스트가 표시됩니다.",
        "또한, DataList 를 바인딩 했을때 GridView 에서 행을 선택하지 않으면 PlaceHolder 텍스트가 표시됩니다.",
        "readOnly=true 이거나 disabled=true 이면 PlaceHolder 기능이 적용되지 않습니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출 (gdm_ref, gdl_boolean)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값 1=미설정 / 2=true / 3=false)
    con_placeholder.setSelectedIndex(1);
    con_ref.setSelectedIndex(1);
    con_readOnly.setValue("1");
    con_disabled.setValue("1");

    // GridView 에 바인딩할 DataList (중복 생성 방지를 위해 1회만 생성)
    await $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof gv1 !== 'undefined') {
        gv1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    await $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 con_placeholder, con_ref, con_readOnly, con_disabled 에서 선택한 값이 속성으로 적용됩니다\nTarget 재생성 시 gdm_ref.key1 은 빈값으로 비워지고 GridView 의 선택 행은 해제되며 target1 의 값도 빈값으로 초기화됩니다\n아래 GridView 는 dlt_bind DataList 를 바인딩한 픽스처로, ref 를 data:dlt_bind.col1 로 선택했을 때 행 선택 여부를 조작하는 수단입니다\n[절차] 위 조건 선택 -> Target 재생성 -> 검증 목적에 따라 아래 중 하나를 수행\n - 바인딩 데이터가 빈값 : ref 를 data:gdm_ref.key1 로 재생성 -> 표시 상태 확인 -> 바인딩 데이터 설정 -> 표시 상태 확인\n - GridView 행 미선택 : ref 를 data:dlt_bind.col1 로 재생성 -> 표시 상태 확인 -> GridView 의 행을 클릭 -> 표시 상태 확인 -> 행 선택 해제 -> 표시 상태 확인\n - readOnly 또는 disabled : readOnly 또는 disabled 를 true 로 재생성 -> 표시 상태 확인\n[확인] password 라 화면으로 값을 읽을 수 없으므로 결과창의 렌더 placeholder 속성값, 입력창 값과 길이, 바인딩 데이터 값, 그리고 화면에 실제로 보이는 PlaceHolder 텍스트로 판정합니다"', '', 'label1');

    // DataList 행 선택 조작용 GridView (dlt_bind 바인딩)
    await $c.gcm.createBasicGridView('dataList="data:dlt_bind"', '', 'gv1');

    // 테스트 영역 안에 GridView 와 target1 이 함께 보이도록 크기 축소
    gv1.setSize('300px', '150px');

    // 조건 설정
    scwin.gVar["cPlaceholder"] = con_placeholder.getValue();
    scwin.gVar["cRef"] = con_ref.getValue();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();
    scwin.gVar["cDisabled"] = con_disabled.getText();

    // 바인딩 데이터 초기화 (dataMap 은 빈값, DataList 는 행 미선택)
    gdm_ref.set("key1", "");
    dlt_bind.setRowPosition(-1);

    let properties = {
        placeholder : scwin.gVar["cPlaceholder"],
        ref : scwin.gVar["cRef"],
        readOnly : scwin.gVar["cReadOnly"],
        disabled : scwin.gVar["cDisabled"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값을 지워 바인딩 데이터가 빈값인 상태에서 PlaceHolder 를 확인한다
    target1.setValue("");
    gdm_ref.set("key1", "");
    dlt_bind.setRowPosition(-1);

    // 바인딩 종류에 따라 사용 가능한 조작 버튼을 구분
    btn_setData.setDisabled(scwin.gVar["cRef"] !== "data:gdm_ref.key1");
    btn_deselectRow.setDisabled(scwin.gVar["cRef"] !== "data:dlt_bind.col1");
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 렌더된 placeholder 속성 상태 (속성 미생성과 빈 문자열은 다른 상태이므로 구분해서 표기)
scwin.fn_ph = function () {
    let objInput = target1.render;

    if (!objInput.hasAttribute("placeholder"))
        return "속성 없음";

    let strAttr = objInput.getAttribute("placeholder");

    return (strAttr === "") ? "빈 문자열" : strAttr;
}



// 바인딩 된 DataCollection 의 현재 상태 (바인딩이 없으면 빈 문자열)
scwin.fn_bound = function () {
    let cRef = scwin.gVar["cRef"];

    if (cRef === "data:gdm_ref.key1") {
        let strData = gdm_ref.get("key1") || "";

        return " / 바인딩 데이터 값 : " + strData + " (" + strData.length + "자)";
    }

    if (cRef === "data:dlt_bind.col1") {
        let nRow = dlt_bind.getRowPosition();
        let strData = (nRow < 0) ? "" : (dlt_bind.getCellData(nRow, "col1") || "");

        return " / GridView 선택 행 : " + ((nRow < 0) ? "없음" : nRow) + " / 바인딩 데이터 값 : " + strData + " (" + strData.length + "자)";
    }

    return "";
}



// 렌더 placeholder 속성값과 입력창 표시 상태 확인 - validation 1, 2, 3 판정 출력
scwin.btn_getState_onclick = function (e) {
    let objInput = target1.render;
    let strValue = target1.getValue() || "";

    let strOut = "placeholder " + scwin.fn_disp(scwin.gVar["cPlaceholder"]) + " / ref " + scwin.fn_disp(scwin.gVar["cRef"]) + " -> 렌더 placeholder 속성 : " + scwin.fn_ph() + " / 입력창 값 : " + strValue + " (" + strValue.length + "자)" + scwin.fn_bound();

    // readOnly 또는 disabled 를 설정한 경우에만 해당 속성의 적용 상태를 함께 낸다
    if (scwin.gVar["cReadOnly"] !== "" || scwin.gVar["cDisabled"] !== "")
        strOut += " / readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + " / disabled " + scwin.fn_disp(scwin.gVar["cDisabled"]) + " -> readonly 속성 : " + objInput.hasAttribute("readonly") + " / disabled 속성 : " + objInput.hasAttribute("disabled");

    wf_body_bottom.getObj("scwin").setReturnValue(strOut);
}



// dataMap 바인딩 데이터에 값 설정 (validation 1 발동 수단)
scwin.btn_setData_onclick = function (e) {
    gdm_ref.set("key1", "dm_data");
}



// DataList 행 선택 해제 (validation 2 발동 수단)
scwin.btn_deselectRow_onclick = function (e) {
    dlt_bind.setRowPosition(-1);
}
